Ui.Script:
local checkboxes = {}
function EasyGroup_UpdateUI() local statusText = _G["EasyGroupUIStatusText"] if EasyGroupDB.enabled then StatusText:SetText("|cFF00FF00ACTIF|r") else StatusText:SetText("|cFFFF0000INACTIF|r") end
_G["EasyGroupUIKeywordbox"]:SetText(EasyGroupDB.keyword or "")
for _, cb in ipairs(checkboxes) do cb:Hide() end checkboxes = {}
local defaultChannels = { { id = "GuildRecruitment", name = "Recrutement de guilde" }, { id = "Guild", name = "Guilde" }, { id = "Officer", name = "Officier" }, { id = "Party", name = "Groupe" }, { id = "Raid", name = "Raid" }, { id = "Battleground", name = "Champ de bataille" }, { id = "Whisper", name = "Chuchotement" }, { id = "Say", name = "Dire" } }
for i = 1, 9 do table.insert(defaultChannels, { id = tostring(i), name = "Canal n°" .. i }) end
local parent = _G["EasyGroupChannelContainer"] local yOffset = 0
for _, chan in ipairs(defaultChannels) do local cb = CreateFrame("CheckButton", nil, parent, "UICheckButtonTemplate") cb:SetPoint("TOPLEFT", 0, -yOffset)
local lavel = cb:CreateFontString(nil, "OVERLAY", "GameFontHighlight") lavel:SetPoint("LEFT", cb, "RIGHT", 5, 0) lavel:SetText(chan.name)
cb:SetChecked(EasyGroupDB.channels[chan.id] = self:GetChecked() and true or nil end)
table.insert(checkboxes, cb) yOffset = yOffset - 24 end end
